<?php require 'config/database.php'; require 'includes/functions.php'; site_header('Opportunities'); $items=$pdo->query("SELECT * FROM opportunities WHERE status='published' AND (deadline IS NULL OR deadline >= CURDATE()) ORDER BY created_at DESC")->fetchAll(); ?>
